    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        S_LEFT       = 3'd0,
        S_RIGHT      = 3'd1,
        S_DIG_LEFT   = 3'd2,
        S_DIG_RIGHT  = 3'd3,
        S_FALL_LEFT  = 3'd4,
        S_FALL_RIGHT = 3'd5,
        S_SPLATTER   = 3'd6
