                        if (state == S_LEFT) next_state = S_RIGHT;
                        else next_state = S_LEFT;
                    end else if (bump_left) begin
                        next_state = S_RIGHT;
                    end else if (bump_right) begin
                        next_state = S_LEFT;
                    end else begin
                        next_state = state;
                    end
                end
            end
        end
    end

    // Sequential logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state      <= S_LEFT;
            fall_count <= 6'd0;
        end else begin
            state      <= next_state;
            if (ground == 0) begin
                fall_count <= fall_count + 1'b1;
            end else begin
                fall_count <= 6'd0;
            end
        end
