module tb_TopModule;
    logic clk;
    logic areset;
    logic bump_left;
    logic bump_right;
    logic ground;
    logic dig;
    logic walk_left;
    logic walk_right;
    logic aaah;
    logic digging;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .ground(ground),
        .dig(dig),
        .walk_left(walk_left),
        .walk_right(walk_right),
        .aaah(aaah),
        .digging(digging)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        bump_left = 0;
        bump_right = 0;
        ground = 1;
        dig = 0;
        #12;
        areset = 0;
        #10;

        // Test 1: Walk left initially
        assert(walk_left == 1 && walk_right == 0 && aaah == 0 && digging == 0) else $error("Reset failed");

        // Test 2: Bump left -> walk right
        bump_left = 1;
        #10;
        bump_left = 0;
        #10;
        assert(walk_right == 1) else $error("Bump left failed to walk right");

        // Test 3: Fall (<20 cycles)
        ground = 0;
        #10;
        assert(aaah == 1 && walk_left == 0 && walk_right == 0) else $error("Fall output failed");
        #30; // fall for 3 cycles total
        ground = 1;
        #10;
        assert(walk_right == 1) else $error("Resume walking right after short fall failed");

        // Test 4: Dig
        dig = 1;
        #10;
        dig = 0;
        assert(digging == 1 && walk_right == 0) else $error("Digging output failed");

        // Ground drops while digging -> fall
        ground = 0;
        #10;
        assert(aaah == 1 && digging == 0) else $error("Digging to fall failed");
        ground = 1;
        #10;
        assert(walk_right == 1) else $error("Resume walking right after dig-fall failed");

        // Test 5: Fall > 20 cycles -> splatter
        ground = 0;
        repeat (22) @(posedge clk);
        ground = 1;
        @(posedge clk);
        assert(walk_left == 0 && walk_right == 0 && aaah == 0 && digging == 0) else $error("Splatter failed");

        // Reset
        areset = 1;
        #10;
        areset = 0;
        #10;
        assert(walk_left == 1) else $error("Reset after splatter failed");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

