module tb_TopModule;
    logic clk;
    logic areset;
    logic bump_left;
    logic bump_right;
    logic ground;
    logic dig;
    logic walk_left;
    logic walk_right;
    logic aaah;
    logic digging;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .ground(ground),
        .dig(dig),
        .walk_left(walk_left),
        .walk_right(walk_right),
        .aaah(aaah),
        .digging(digging)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        areset = 1;
        bump_left = 0;
        bump_right = 0;
        ground = 1;
        dig = 0;
        #12;
        areset = 0;
        #10;

        // 1. Initial walk left
        assert(walk_left == 1 && walk_right == 0 && aaah == 0 && digging == 0) else $error("T1 fail");

        // 2. Bump left -> walk right
        bump_left = 1;
        #10;
        bump_left = 0;
        #10;
        assert(walk_right == 1 && walk_left == 0) else $error("T2 fail");

        // 3. Bump right -> walk left
        bump_right = 1;
        #10;
        bump_right = 0;
        #10;
        assert(walk_left == 1 && walk_right == 0) else $error("T3 fail");

        // 4. Simultaneous bumps -> switch direction (walk right)
        bump_left = 1;
        bump_right = 1;
        #10;
        bump_left = 0;
        bump_right = 0;
        #10;
        assert(walk_right == 1) else $error("T4 fail");

        // 5. Fall and recover (< 20 cycles)
        ground = 0;
        #10;
        assert(aaah == 1 && walk_left == 0 && walk_right == 0 && digging == 0) else $error("T5 fall fail");
        repeat (5) @(posedge clk);
        ground = 1;
        @(posedge clk);
        assert(walk_right == 1 && aaah == 0) else $error("T5 recover fail");

        // 6. Digging
        dig = 1;
        @(posedge clk);
        dig = 0;
        @(posedge clk);
        assert(digging == 1 && walk_right == 0) else $error("T6 dig start fail");

        // Ground drops while digging -> fall
        ground = 0;
        @(posedge clk);
        assert(aaah == 1 && digging == 0) else $error("T6 dig fall fail");
        ground = 1;
        @(posedge clk);
        assert(walk_right == 1 && aaah == 0) else $error("T6 dig fall recover fail");

        // 7. Splatter test (> 20 cycles fall)
        ground = 0;
        repeat (22) @(posedge clk);
        ground = 1;
        @(posedge clk);
        @(posedge clk);
        assert(walk_left == 0 && walk_right == 0 && aaah == 0 && digging == 0) else $error("T7 splatter fail");

        // 8. Reset after splatter
        areset = 1;
        #10;
        areset = 0;
        #10;
        assert(walk_left == 1) else $error("T8 reset fail");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

